package com.kareem.cortex;

import android.app.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.util.*;

public class VaultActivity extends Activity {
    VaultDb db;LinearLayout feed,tabs;String filter="ALL";int bg=Color.rgb(11,12,14),surface=Color.rgb(24,26,30),text=Color.rgb(245,244,240),muted=Color.rgb(156,159,168),accent=Color.rgb(232,177,72),danger=Color.rgb(246,124,118),ok=Color.rgb(120,205,150),border=Color.rgb(47,50,57);
    int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}TextView plain(String s,int sp,int c){TextView v=new TextView(this);v.setTextSize(sp);v.setTextColor(c);CortexTextUi.setPlain(v,s);return v;}TextView readable(String s,int sp,int c){TextView v=new TextView(this);v.setTextSize(sp);v.setTextColor(c);CortexTextUi.setReadable(v,s);return v;}GradientDrawable round(int fill,int stroke,int r){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(r));g.setStroke(dp(1),stroke);return g;}
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new VaultDb(this);ScreenshotLearning.ensure(db);V43Maintenance.run(this,db);build();refresh();}
    @Override protected void onResume(){super.onResume();if(db!=null)refresh();ScreenshotWorkScheduler.kick(this);}
    void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);root.setPadding(dp(16),dp(16),dp(16),0);TextView h=plain("VAULT",28,text);h.setTypeface(null,1);root.addView(h);TextView s=plain("Original captures and evidence. Brain outputs always trace back here.",13,muted);s.setPadding(0,dp(3),0,dp(12));root.addView(s);HorizontalScrollView hsv=new HorizontalScrollView(this);hsv.setHorizontalScrollBarEnabled(false);tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);hsv.addView(tabs);root.addView(hsv,new LinearLayout.LayoutParams(-1,dp(44)));ScrollView sv=new ScrollView(this);feed=new LinearLayout(this);feed.setOrientation(LinearLayout.VERTICAL);sv.addView(feed);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    void refresh(){tabs.removeAllViews();String[] fs={"ALL","VOICE","SCREENSHOTS","FILES","TEXT"};for(String f:fs)addTab(f);feed.removeAllViews();ArrayList<KnowledgeItem> all=db.lexicalSearch("",2000);int shown=0;for(KnowledgeItem k:all){if(!match(k))continue;addCard(k);shown++;}if(shown==0){TextView e=plain("No captures in this view yet.",14,muted);e.setPadding(dp(8),dp(40),dp(8),dp(40));feed.addView(e);}}
    void addTab(String f){TextView t=plain(f,10,f.equals(filter)?accent:muted);t.setGravity(Gravity.CENTER);if(f.equals(filter))t.setTypeface(null,1);t.setBackground(round(surface,f.equals(filter)?accent:border,999));t.setOnClickListener(v->{filter=f;refresh();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(34));p.setMargins(0,0,dp(7),0);p.width=dp(Math.max(68,f.length()*9+24));tabs.addView(t,p);}
    boolean match(KnowledgeItem k){if("ALL".equals(filter))return true;if("VOICE".equals(filter))return "AUDIO".equals(k.type);if("SCREENSHOTS".equals(filter))return isShot(k);if("FILES".equals(filter))return "FILE".equals(k.type);return !"AUDIO".equals(k.type)&&!isShot(k)&&!"FILE".equals(k.type);}
    boolean isShot(KnowledgeItem k){return "SCREENSHOT".equals(k.type)||"IMAGE".equals(k.type);}
    void addCard(KnowledgeItem k){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(14),dp(15),dp(14));c.setBackground(round(surface,border,20));c.setClickable(true);c.setOnClickListener(v->detail(k));TextView t=readable(clean(k.title),16,text);t.setTypeface(null,1);t.setMaxLines(2);c.addView(t);String state=statusLabel(k);TextView meta=plain(friendly(k.type)+" • "+k.source+" • "+age(captureTime(k))+" • "+state,11,statusColor(k));meta.setPadding(0,dp(5),0,0);c.addView(meta);String raw=raw(k);if(!raw.isEmpty()){TextView b=readable(clip(raw,220),13,text);b.setPadding(0,dp(9),0,0);b.setMaxLines(4);c.addView(b);}if(isShot(k)&&"analyzed".equals(k.status)){ArrayList<String> vf=db.visionFields(k.id);if(!vf.isEmpty()){TextView x=plain("Structured data: "+vf.size()+" fields",11,accent);x.setPadding(0,dp(8),0,0);c.addView(x);}ArrayList<String> selected=ScreenshotLearning.selected(db,k.id);if(!selected.isEmpty()){TextView x=plain("Taught: "+String.join(" • ",selected),11,ok);x.setPadding(0,dp(6),0,0);x.setMaxLines(2);c.addView(x);}}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));feed.addView(c,p);}
    String statusLabel(KnowledgeItem k){if("analyzed".equals(k.status))return isShot(k)?"OCR analyzed":"Analyzed";if("queued".equals(k.status))return "Queued";if("analyzing".equals(k.status))return "Analyzing";if("analysis_failed".equals(k.status)||"failed_retryable".equals(k.status))return isShot(k)?"OCR failed":"Analysis failed";return k.status==null?"":k.status;}
    int statusColor(KnowledgeItem k){if("analyzed".equals(k.status))return ok;if("analysis_failed".equals(k.status)||"failed_retryable".equals(k.status))return danger;return muted;}

    void detail(KnowledgeItem k){ScrollView sv=new ScrollView(this);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(18),dp(8),dp(18),dp(18));sv.addView(b);label(b,"SOURCE");b.addView(plain(friendly(k.type)+" • "+k.source+"\nCaptured: "+new java.text.SimpleDateFormat("dd MMM yyyy • HH:mm",Locale.getDefault()).format(new Date(captureTime(k)))+"\nImported: "+new java.text.SimpleDateFormat("dd MMM yyyy • HH:mm",Locale.getDefault()).format(new Date(k.createdAt))+"\nStatus: "+statusLabel(k),12,muted));if(k.attachmentPath!=null&&!k.attachmentPath.isEmpty()){label(b,"ARCHIVED FILE");b.addView(plain(k.attachmentPath,11,muted));}if(k.rawText!=null&&!k.rawText.trim().isEmpty()){label(b,"RAW DATA");b.addView(readable(k.rawText,13,text));}if(k.extractedText!=null&&!k.extractedText.trim().isEmpty()){label(b,"EXTRACTED / OCR / TRANSCRIPT");b.addView(readable(k.extractedText,13,text));}if(k.summary!=null&&!k.summary.trim().isEmpty()){label(b,"DERIVED SUMMARY");b.addView(readable(k.summary,13,text));}ArrayList<String> vf=db.visionFields(k.id);if(!vf.isEmpty()){label(b,"STRUCTURED EXTRACTION");b.addView(readable(bullets(vf),12,text));}
        if(isShot(k)){ArrayList<String> chosen=ScreenshotLearning.selected(db,k.id);String type=ScreenshotLearning.contentType(db,k.id);String[] opts=ScreenshotLearning.options(type);boolean[] suggestions=ScreenshotLearning.suggested(db,type,opts);int suggested=0;for(boolean q:suggestions)if(q)suggested++;label(b,"WHAT MATTERS TO YOU");String learned=suggested>0?"\nCortex has "+suggested+" learned default suggestion(s) for this type.":"";b.addView(readable((chosen.isEmpty()?"Not taught yet. Tell Cortex what to prioritize from this screenshot.":bullets(chosen))+learned,12,chosen.isEmpty()?muted:text));Button teach=button("TEACH CORTEX WHAT MATTERS");teach.setOnClickListener(v->teach(k));b.addView(teach,new LinearLayout.LayoutParams(-1,dp(48)));if("analysis_failed".equals(k.status)||"failed_retryable".equals(k.status)){Button retry=button("RETRY OCR");retry.setOnClickListener(v->{db.retry(k.id);ScreenshotWorkScheduler.kick(this);Toast.makeText(this,"OCR retry queued in durable worker",Toast.LENGTH_SHORT).show();refresh();});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(48));rp.setMargins(0,dp(8),0,0);b.addView(retry,rp);}}
        new AlertDialog.Builder(this).setTitle(clean(k.title)).setView(sv).setNegativeButton("Close",null).show();}
    Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setTextColor(text);b.setAllCaps(false);b.setBackground(round(surface,border,16));return b;}
    void teach(KnowledgeItem k){String type=ScreenshotLearning.contentType(db,k.id);String[] opts=ScreenshotLearning.options(type);boolean[] checked=ScreenshotLearning.suggested(db,type,opts);for(String old:ScreenshotLearning.selected(db,k.id))for(int i=0;i<opts.length;i++)if(opts[i].equals(old))checked[i]=true;new AlertDialog.Builder(this).setTitle("What matters here? • "+type).setMultiChoiceItems(opts,checked,(d,w,on)->checked[w]=on).setPositiveButton("Save",(d,w)->{ScreenshotLearning.record(db,k.id,type,opts,checked);Toast.makeText(this,"Cortex learned your priorities for this screenshot",Toast.LENGTH_LONG).show();refresh();}).setNegativeButton("Cancel",null).show();}
    long captureTime(KnowledgeItem k){if(k.metadataJson!=null&&!k.metadataJson.isEmpty())try{org.json.JSONObject o=new org.json.JSONObject(k.metadataJson);long x=o.optLong("source_modified",0);if(x>0)return x;}catch(Exception ignored){}return k.createdAt;}
    void label(LinearLayout p,String s){TextView h=plain(s,11,accent);h.setTypeface(null,1);h.setPadding(0,dp(14),0,dp(6));p.addView(h);}String raw(KnowledgeItem k){if(k.rawText!=null&&!k.rawText.trim().isEmpty())return k.rawText;if(k.extractedText!=null&&!k.extractedText.trim().isEmpty())return k.extractedText;return k.summary==null?"":k.summary;}String clean(String s){if(s==null||s.trim().isEmpty())return "Memory";String x=s.trim();if(x.regionMatches(true,0,"Voice:",0,6))x=x.substring(6).trim();return x;}String friendly(String s){if("AUDIO".equals(s))return "Voice";if("SCREENSHOT".equals(s))return "Screenshot";if("IMAGE".equals(s))return "Image";return s==null?"Memory":s;}String clip(String s,int n){return s.length()<=n?s:s.substring(0,n)+"…";}String bullets(ArrayList<String> xs){StringBuilder s=new StringBuilder();for(String x:xs)s.append("• ").append(x).append('\n');return s.toString().trim();}String age(long ms){long m=Math.max(0,System.currentTimeMillis()-ms)/60000;if(m<1)return "now";if(m<60)return m+"m";long h=m/60;if(h<24)return h+"h";return h/24+"d";}
}
